import 'package:flutter/material.dart';
import '../services/api.dart';
class VehicleHistoryScreen extends StatefulWidget{final String vehicle;const VehicleHistoryScreen({super.key,required this.vehicle});@override State<VehicleHistoryScreen> createState()=>_VehicleHistoryScreenState();}
class _VehicleHistoryScreenState extends State<VehicleHistoryScreen>{bool loading=true;String? error;Map<String,dynamic>? data;int tab=0;
@override void initState(){super.initState();load();}Future<void> load()async{try{data=await Api.instance.vehicleHistory(widget.vehicle);}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}
@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(error!=null)return Scaffold(appBar:AppBar(title:Text(widget.vehicle)),body:Center(child:Text(error!)));final p=List<dynamic>.from(data!['problems']??[]);final r=List<dynamic>.from(data!['readings']??[]);final v=Map<String,dynamic>.from(data!['vidange']??{});const tabs=['ALL','PROBLEMS','ACCIDENTS','VIDANGE','KM'];return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(widget.vehicle)),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(10),child:Row(children:List.generate(tabs.length,(i)=>Padding(padding:const EdgeInsetsDirectional.only(end:6),child:ChoiceChip(label:Text(tabs[i]),selected:tab==i,onSelected:(_)=>setState(()=>tab=i))))),Expanded(child:body(p,r,v))])));}
Widget body(List<dynamic> p,List<dynamic> r,Map<String,dynamic> v){if(tab==4)return ListView.builder(itemCount:r.length,itemBuilder:(_,i){final x=Map<String,dynamic>.from(r[i]);return ListTile(leading:const Icon(Icons.speed),title:Text(x['km'].toString()+' KM'),subtitle:Text(x['date'].toString()));});if(tab==3)return ListView(children:[ListTile(title:const Text('آخر Vidange'),trailing:Text((v['last_vidange_km']??'-').toString()+' KM')),ListTile(title:const Text('Vidange القادمة'),trailing:Text((v['next_vidange_km']??'-').toString()+' KM')),ListTile(title:const Text('آخر KM'),trailing:Text((v['latest_km']??'-').toString()+' KM')),ListTile(title:const Text('المتبقي'),trailing:Text((v['remaining_km']??'-').toString()+' KM'))]);final f=tab==2?p.where((x)=>x['problem_type']=='accident').toList():tab==1?p.where((x)=>x['problem_type']!='accident'&&x['problem_type']!='vidange').toList():p;return ListView.builder(itemCount:f.length,itemBuilder:(_,i){final x=Map<String,dynamic>.from(f[i]);return ListTile(title:Text(x['problem_text']?.toString()??''),subtitle:Text(x['date']?.toString()??''));});}}
